CREATE TABLE IF NOT EXISTS semob_imports(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,sha256 TEXT UNIQUE NOT NULL,created_at TEXT NOT NULL,statistics TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS semob_lines(code TEXT PRIMARY KEY,name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS semob_vehicles(code TEXT PRIMARY KEY);
CREATE TABLE IF NOT EXISTS semob_operation_daily(day TEXT PRIMARY KEY,fleet INTEGER,fleet_planned INTEGER,trips_planned INTEGER CHECK(trips_planned>=0),trips_completed INTEGER CHECK(trips_completed>=0),trips_missed INTEGER CHECK(trips_missed>=0),km_productive NUMERIC CHECK(km_productive>=0),km_unproductive NUMERIC CHECK(km_unproductive>=0),km_total NUMERIC CHECK(km_total>=0),priority INTEGER NOT NULL CHECK(priority IN (1,2)),source TEXT NOT NULL,import_id INTEGER NOT NULL REFERENCES semob_imports(id));
CREATE TABLE IF NOT EXISTS semob_passenger_daily(day TEXT PRIMARY KEY,paid INTEGER,unpaid INTEGER,passengers INTEGER,cash_passengers INTEGER,prepaid_passengers INTEGER,priority INTEGER NOT NULL CHECK(priority IN (1,2)),source TEXT NOT NULL,import_id INTEGER NOT NULL REFERENCES semob_imports(id));
CREATE TABLE IF NOT EXISTS semob_finance_daily(day TEXT PRIMARY KEY,sales NUMERIC,usage NUMERIC,circulating NUMERIC,priority INTEGER NOT NULL CHECK(priority IN (1,2)),source TEXT NOT NULL,import_id INTEGER NOT NULL REFERENCES semob_imports(id));
CREATE TABLE IF NOT EXISTS semob_line_daily(day TEXT NOT NULL,line_code TEXT NOT NULL REFERENCES semob_lines(code),km_productive NUMERIC,trips_completed INTEGER,priority INTEGER NOT NULL,source TEXT NOT NULL,import_id INTEGER NOT NULL REFERENCES semob_imports(id),PRIMARY KEY(day,line_code));
CREATE TABLE IF NOT EXISTS semob_documents(id INTEGER PRIMARY KEY AUTOINCREMENT,import_id INTEGER NOT NULL REFERENCES semob_imports(id),source TEXT NOT NULL,table_index INTEGER NOT NULL,sha256 TEXT NOT NULL,document TEXT NOT NULL,UNIQUE(import_id,source,table_index));
CREATE TABLE IF NOT EXISTS semob_trips(id INTEGER PRIMARY KEY AUTOINCREMENT,import_id INTEGER NOT NULL REFERENCES semob_imports(id),day TEXT NOT NULL,line_code TEXT REFERENCES semob_lines(code),vehicle_code TEXT REFERENCES semob_vehicles(code),priority INTEGER NOT NULL,source TEXT NOT NULL,start_time TEXT,km_productive NUMERIC,km_unproductive NUMERIC,document TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS semob_trips_day_rank ON semob_trips(day,priority,import_id);
CREATE INDEX IF NOT EXISTS semob_trips_line ON semob_trips(line_code);
